ALTER TABLE projects ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE projects ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE tasks ADD COLUMN title TEXT NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN detail TEXT NOT NULL DEFAULT '';
ALTER TABLE tasks ADD COLUMN macro_item_id TEXT REFERENCES plan_items(id);
ALTER TABLE tasks ADD COLUMN forced_level INTEGER NOT NULL DEFAULT 0;
ALTER TABLE tasks ADD COLUMN estimate_seconds INTEGER;
ALTER TABLE tasks ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE plans ADD COLUMN title TEXT NOT NULL DEFAULT '';
ALTER TABLE plans ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE plan_items ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE requirements ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE criteria ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE criteria ADD COLUMN instruction_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE criteria ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE checks ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE checks ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE evidence ADD COLUMN instruction_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE evidence ADD COLUMN evidence_kind TEXT NOT NULL DEFAULT 'execution';
ALTER TABLE evidence ADD COLUMN stale INTEGER NOT NULL DEFAULT 0;
ALTER TABLE evidence ADD COLUMN trusted INTEGER NOT NULL DEFAULT 0;
ALTER TABLE evidence ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE milestones ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE milestones ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE assumptions ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE decisions ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE project_log ADD COLUMN version INTEGER NOT NULL DEFAULT 1;
CREATE TABLE task_requirements(task_id TEXT NOT NULL REFERENCES tasks(id),requirement_id TEXT NOT NULL REFERENCES requirements(id),PRIMARY KEY(task_id,requirement_id));
CREATE TABLE task_entity_versions(entity TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),recorded_at INTEGER NOT NULL,PRIMARY KEY(entity,id,version));
CREATE TABLE task_plan_versions(plan_id TEXT NOT NULL REFERENCES plans(id),version INTEGER NOT NULL,snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),recorded_at INTEGER NOT NULL,PRIMARY KEY(plan_id,version));
CREATE TABLE task_batch_receipts(scope_id TEXT NOT NULL,principal_key TEXT NOT NULL,operation_key TEXT NOT NULL,request_hash TEXT NOT NULL,result TEXT NOT NULL CHECK(json_valid(result)),PRIMARY KEY(scope_id,principal_key,operation_key));
CREATE TABLE task_drafts(scope_id TEXT NOT NULL,principal_key TEXT NOT NULL,id TEXT NOT NULL,entity TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(scope_id,principal_key,id));
CREATE TABLE task_run_links(run_id TEXT PRIMARY KEY REFERENCES runs(id),task_id TEXT NOT NULL REFERENCES tasks(id),parent_run_id TEXT REFERENCES runs(id));
CREATE INDEX task_run_parent ON task_run_links(parent_run_id);
CREATE TABLE task_root_history(task_id TEXT NOT NULL REFERENCES tasks(id),run_id TEXT NOT NULL REFERENCES runs(id),ordinal INTEGER NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(task_id,run_id),UNIQUE(task_id,ordinal));
CREATE TABLE task_directives(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),run_id TEXT NOT NULL REFERENCES runs(id),revision INTEGER NOT NULL,content TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE TABLE task_control_ops(id TEXT PRIMARY KEY,operation_key TEXT UNIQUE NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),kind TEXT NOT NULL,confirmed INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'pending',reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE task_control_members(operation_id TEXT NOT NULL REFERENCES task_control_ops(id),run_id TEXT NOT NULL REFERENCES runs(id),prior_state TEXT NOT NULL,depth INTEGER NOT NULL,applied INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(operation_id,run_id));
CREATE TABLE task_plan_proposals(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES plans(id),expected_version INTEGER NOT NULL,operation_key TEXT UNIQUE NOT NULL,operations TEXT NOT NULL CHECK(json_valid(operations)),request_hash TEXT NOT NULL,affected TEXT NOT NULL CHECK(json_valid(affected)),frozen TEXT NOT NULL CHECK(json_valid(frozen)),reason TEXT NOT NULL,requires_approval INTEGER NOT NULL,approved INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'proposed',created_at INTEGER NOT NULL);
CREATE TABLE task_plan_approvals(proposal_id TEXT PRIMARY KEY REFERENCES task_plan_proposals(id),approved INTEGER NOT NULL,actor TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE task_notebook(id TEXT PRIMARY KEY,scope_id TEXT NOT NULL,principal_id TEXT REFERENCES principals(id),text TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX task_dependency_unique ON dependencies(scope_id,from_id,to_id,kind);
CREATE TRIGGER task_state_from_root_insert AFTER INSERT ON tasks WHEN NEW.root_run_id IS NOT NULL BEGIN UPDATE tasks SET derived_state=COALESCE((SELECT CASE WHEN state IN('ready','running','waiting','verifying','recovering') THEN 'in_progress' WHEN state IN('created','pending') THEN 'open' ELSE state END FROM runs WHERE id=NEW.root_run_id),'open') WHERE id=NEW.id; END;
CREATE TRIGGER task_state_from_root_binding AFTER UPDATE OF root_run_id ON tasks BEGIN UPDATE tasks SET derived_state=COALESCE((SELECT CASE WHEN state IN('ready','running','waiting','verifying','recovering') THEN 'in_progress' WHEN state IN('created','pending') THEN 'open' ELSE state END FROM runs WHERE id=NEW.root_run_id),'open') WHERE id=NEW.id; END;
CREATE TRIGGER task_state_from_run AFTER UPDATE OF state ON runs BEGIN UPDATE tasks SET derived_state=CASE WHEN NEW.state IN('ready','running','waiting','verifying','recovering') THEN 'in_progress' WHEN NEW.state IN('created','pending') THEN 'open' ELSE NEW.state END WHERE root_run_id=NEW.id; END;

CREATE TABLE task_observed_events(run_id TEXT NOT NULL REFERENCES runs(id),sequence INTEGER NOT NULL,payload_hash TEXT NOT NULL,PRIMARY KEY(run_id,sequence));
UPDATE tasks SET scope_id=COALESCE(project_id,'general'),derived_state=CASE WHEN root_run_id IS NULL THEN 'open' ELSE derived_state END WHERE scope_id IS NULL;
UPDATE requirements SET scope_id=COALESCE(project_id,'general') WHERE scope_id IS NULL;
UPDATE projects SET scope_id=id WHERE scope_id IS NULL;
UPDATE plans SET scope_id=COALESCE((SELECT scope_id FROM tasks WHERE id=owner_task_id),'general') WHERE scope_id IS NULL;
UPDATE plan_items SET scope_id=COALESCE((SELECT scope_id FROM plans WHERE id=plan_id),'general') WHERE scope_id IS NULL;
UPDATE milestones SET scope_id=COALESCE(project_id,'general') WHERE scope_id IS NULL;
UPDATE criteria SET scope_id=COALESCE((SELECT scope_id FROM requirements WHERE id=requirement_id),'general') WHERE scope_id IS NULL;
UPDATE checks SET scope_id=COALESCE((SELECT scope_id FROM criteria WHERE id=criterion_id),'general') WHERE scope_id IS NULL;
UPDATE evidence SET scope_id=COALESCE((SELECT scope_id FROM checks WHERE id=check_id),'general') WHERE scope_id IS NULL;
CREATE TABLE task_impact_roots(criterion_id TEXT NOT NULL REFERENCES criteria(id),scope_id TEXT NOT NULL,prefix TEXT NOT NULL,PRIMARY KEY(criterion_id,prefix));
CREATE INDEX task_impact_prefix ON task_impact_roots(scope_id,prefix);
ALTER TABLE assumptions ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE decisions ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
ALTER TABLE project_log ADD COLUMN metadata TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(metadata));
CREATE TABLE task_replan_requests(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),scope_id TEXT NOT NULL,principal_id TEXT REFERENCES principals(id),reason TEXT NOT NULL,changed TEXT NOT NULL CHECK(json_valid(changed)),affected TEXT NOT NULL CHECK(json_valid(affected)),state TEXT NOT NULL DEFAULT 'pending',version INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE task_milestone_closures(milestone_id TEXT PRIMARY KEY REFERENCES milestones(id),version INTEGER NOT NULL,verifier_job_id TEXT REFERENCES task_verifier_jobs(id),criterion_versions TEXT NOT NULL CHECK(json_valid(criterion_versions)),root_run_id TEXT NOT NULL REFERENCES runs(id),instruction_revision INTEGER NOT NULL,closed_at INTEGER NOT NULL);
